import { useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const addDays = (date: Date, amount: number): Date => {
  const next = startOfDay(date);
  next.setDate(next.getDate() + amount);
  return next;
};

const isSameDay = (a: Date, b: Date): boolean =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

const buildMonthGrid = (monthStart: Date): Date[] => {
  const leadingEmptyDays = (monthStart.getDay() + 6) % 7;
  const gridStart = addDays(monthStart, -leadingEmptyDays);
  return Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
};

const formatMonthTitle = (monthStart: Date): string =>
  monthStart.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' });

const formatFullDate = (date: Date): string =>
  date.toLocaleDateString('ru-RU', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });

function ReportDatePicker({ value, defaultValue, onChange }: ReportDatePickerProps) {
  const [uncontrolledDate, setUncontrolledDate] = useState<Date>(() =>
    startOfDay(defaultValue ?? new Date()),
  );

  const selectedDate = value ? startOfDay(value) : uncontrolledDate;

  const [viewMonth, setViewMonth] = useState<Date>(
    () => new Date(selectedDate.getFullYear(), selectedDate.getMonth(), 1),
  );

  const quickOptions = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ];
  }, []);

  const days = useMemo(() => buildMonthGrid(viewMonth), [viewMonth]);

  const selectDate = (date: Date): void => {
    const normalized = startOfDay(date);
    setUncontrolledDate(normalized);
    setViewMonth(new Date(normalized.getFullYear(), normalized.getMonth(), 1));
    onChange(normalized);
  };

  const shiftMonth = (amount: number): void => {
    setViewMonth((current) => new Date(current.getFullYear(), current.getMonth() + amount, 1));
  };

  return (
    <Card>
      <Stack direction="vertical" gap="md">
        <Stack direction="horizontal" gap="sm" wrap>
          {quickOptions.map((option) => (
            <Button
              key={option.label}
              type="button"
              size="sm"
              variant={isSameDay(option.date, selectedDate) ? 'primary' : 'secondary'}
              aria-pressed={isSameDay(option.date, selectedDate)}
              onClick={() => selectDate(option.date)}
            >
              {option.label}
            </Button>
          ))}
        </Stack>

        <Stack direction="horizontal" gap="sm" align="center" justify="space-between">
          <Button
            type="button"
            size="sm"
            variant="ghost"
            aria-label="Предыдущий месяц"
            onClick={() => shiftMonth(-1)}
          >
            ←
          </Button>
          <Text weight="medium" aria-live="polite">
            {formatMonthTitle(viewMonth)}
          </Text>
          <Button
            type="button"
            size="sm"
            variant="ghost"
            aria-label="Следующий месяц"
            onClick={() => shiftMonth(1)}
          >
            →
          </Button>
        </Stack>

        <div
          role="grid"
          aria-label="Календарь на месяц"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-xs)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" align="center" style={{ color: 'var(--jx-color-text-muted)' }}>
              {weekday}
            </Text>
          ))}

          {days.map((day) => {
            const isCurrentMonth = day.getMonth() === viewMonth.getMonth();
            const isSelected = isSameDay(day, selectedDate);

            return (
              <Button
                key={day.toISOString()}
                type="button"
                size="sm"
                fullWidth
                variant={isSelected ? 'primary' : 'ghost'}
                aria-selected={isSelected}
                aria-label={formatFullDate(day)}
                style={isCurrentMonth || isSelected ? undefined : { color: 'var(--jx-color-text-muted)' }}
                onClick={() => selectDate(day)}
              >
                {day.getDate()}
              </Button>
            );
          })}
        </div>

        <Text size="sm" style={{ color: 'var(--jx-color-text-muted)' }}>
          Дата отчёта: {formatFullDate(selectedDate)}
        </Text>
      </Stack>
    </Card>
  );
}

export default ReportDatePicker;

